class TestSanitizeChatInput:
    """Core functional tests for the sanitizer."""

    def test_normal_input_returns_original(
        self, valid_utf8_payload: bytes
    ):
        """Valid UTF-8 payload should pass through unchanged."""
        result = sanitize_chat_input(valid_utf8_payload)
        assert result == valid_utf8_payload.decode("utf-8")
        assert isinstance(result, str)

    def test_empty_payload(self):
        """Empty input should return empty string."""
        result = sanitize_chat_input(b"")
        assert result == ""

    def test_unicode_multibyte_preserved(self):
        """Multi-byte Unicode characters must not be corrupted."""
        payload = "日本語テキスト🎉".encode("utf-8")
        result = sanitize_chat_input(payload)
        assert result == "日本語テキスト🎉"

    def test_control_characters_preserved(self):
        """Control characters (e.g., \n, \t) should be preserved."""
        payload = b"line1\nline2\tindented"
        result = sanitize_chat_input(payload)
        assert result == "line1\nline2\tindented"

    def test_ascii_only(self):
        """Pure ASCII payload."""
        payload = b"simple ascii"
        result = sanitize_chat_input(payload)
        assert result == "simple ascii"

    def test_whitespace_only(self):
        """Whitespace-only payload."""
        payload = b"   \n\t  "
        result = sanitize_chat_input(payload)
        assert result == "   \n\t  "


class TestOversizedPayload:
    """Tests for the 2 MiB hard limit."""

    def test_oversized_truncates_to_limit(
        self, oversized_payload: bytes
    ):
        """Payload larger than limit should be truncated to MAX_PAYLOAD_BYTES."""
        result = sanitize_chat_input(oversized_payload)
        assert len(result.encode("utf-8")) == MAX_PAYLOAD_BYTES
        assert result == "A" * MAX_PAYLOAD_BYTES

    def test_oversized_does_not_raise(self, oversized_payload: bytes):
        """Truncation should not raise an exception."""
        try:
            sanitize_chat_input(oversized_payload)
        except SanitizerError:
            pytest.fail("Oversized payload should not raise SanitizerError")

    def test_exact_boundary_passes(self, boundary_payload: bytes):
        """Payload exactly at limit should pass without truncation."""
        result = sanitize_chat_input(boundary_payload)
        assert len(result.encode("utf-8")) == MAX_PAYLOAD_BYTES
        assert result == "B" * MAX_PAYLOAD_BYTES

    def test_just_over_boundary_truncates(self):
        """Payload 1 byte over limit should truncate to limit."""
        payload = b"C" * (MAX_PAYLOAD_BYTES + 1)
        result = sanitize_chat_input(payload)
        assert len(result.encode("utf-8")) == MAX_PAYLOAD_BYTES
        assert result == "C" * MAX_PAYLOAD_BYTES

    def test_truncation_preserves_utf8_boundary(self):
        """Truncation must not split a multi-byte UTF-8 character."""
        # Create payload where truncation point falls in the middle of a
        # 4-byte character (e.g., emoji). We need to ensure the Rust
        # implementation uses `from_utf8_lossy` which handles this.
        base = "😀" * (MAX_PAYLOAD_BYTES // 4 + 1)
        payload = base.encode("utf-8")
        result = sanitize_chat_input(payload)
        # Result should be valid UTF-8 (lossy conversion replaces invalid)
        result.encode("utf-8")  # Should not raise
        assert len(result.encode("utf-8")) <= MAX_PAYLOAD_BYTES


class TestInvalidUtf8:
    """Tests for invalid UTF-8 handling."""

    def test_invalid_utf8_raises_error(self, invalid_utf8_payload: bytes):
        """Invalid UTF-8 should raise SanitizerError."""
        with pytest.raises(SanitizerError) as exc_info:
            sanitize_chat_input(invalid_utf8_payload)
        assert "InvalidUtf8" in str(exc_info.value) or "invalid UTF-8" in str(exc_info.value).lower()

    def test_invalid_utf8_after_truncation(self):
        """Invalid UTF-8 in truncated region should be handled."""
        # Create payload with valid start, invalid bytes at the end
        payload = b"valid" + b"\xff\xfe" * (MAX_PAYLOAD_BYTES // 2)
        # This may truncate or raise; either is acceptable per spec
        try:
            result = sanitize_chat_input(payload)
            # If it returns, must be valid UTF-8
            result.encode("utf-8")
        except SanitizerError:
            pass  # Acceptable per spec

    def test_mixed_valid_invalid_utf8(self):
        """Mixed valid/invalid UTF-8 should either raise or lossy-convert."""
        payload = b"hello\xffworld"
        try:
            result = sanitize_chat_input(payload)
            # If lossy conversion, invalid bytes replaced
            assert "hello" in result
            assert "world" in result
        except SanitizerError:
            pass  # Acceptable per spec


class TestLoggingBehavior:
    """Tests for the trm_paste.log side-effect."""

    def test_oversized_payload_logs_warning(
        self, oversized_payload: bytes, isolated_log_path: Path
    ):
        """Oversized payload should write a WARN entry to the log."""
        sanitize_chat_input(oversized_payload)
        if isolated_log_path.exists():
            log_content = isolated_log_path.read_text()
            assert "WARN" in log_content
            assert "size_exceeded" in log_content
            assert str(len(oversized_payload)) in log_content
            assert str(MAX_PAYLOAD_BYTES) in log_content

    def test_normal_payload_no_warning_log(
        self, valid_utf8_payload: bytes, isolated_log_path: Path
    ):
        """Normal payload should not log a warning."""
        sanitize_chat_input(valid_utf8_payload)
        if isolated_log_path.exists():
            log_content = isolated_log_path.read_text()
            assert "WARN" not in log_content

    def test_log_contains_timestamp(
        self, oversized_payload: bytes, isolated_log_path: Path
    ):
        """Log entry should contain a millisecond timestamp."""
        sanitize_chat_input(oversized_payload)
        if isolated_log_path.exists():
            log_content = isolated_log_path.read_text()
            # Timestamp is 13-digit milliseconds
            import re
            assert re.search(r"\d{13}", log_content)

    def test_log_append_mode(
        self, oversized_payload: bytes, isolated_log_path: Path
    ):
        """Log should append, not overwrite."""
        sanitize_chat_input(oversized_payload)
        sanitize_chat_input(oversized_payload)
        if isolated_log_path.exists():
            log_content = isolated_log_path.read_text()
            assert log_content.count("WARN") == 2


