class TestPerformance:
    """Basic performance sanity checks."""

    def test_large_valid_payload_speed(self):
        """1 MiB valid payload should process quickly (< 1s)."""
        payload = b"x" * (1024 * 1024)
        start = time.perf_counter()
        result = sanitize_chat_input(payload)
        elapsed = time.perf_counter() - start
        assert elapsed < 1.0
        assert len(result) == 1024 * 1024

    def test_repeated_calls_no_state_leak(self):
        """Multiple calls should not affect each other."""
        payloads = [b"test1", b"test2", b"test3"]
        results = [sanitize_chat_input(p) for p in payloads]
        assert results == ["test1", "test2", "test3"]


